INSERT INTO images (created_at, image_url, is_main, car_id) SELECT CURRENT_TIMESTAMP, 'https://example.com/images/bmw-3-series-1.jpg', true, c.id FROM cars c WHERE c.brand_id = (SELECT id FROM brands WHERE name = 'BMW') AND c.model_id = (SELECT id FROM models WHERE name = '3 Series' AND brand_id = (SELECT id FROM brands WHERE name = 'BMW')) LIMIT 1;
