-- ==========================================
-- 3. ROLLAR VƏ İCAZƏLƏRİN ƏLAQƏLƏNDİRİLMƏSİ
-- ==========================================
-- Admin üçün bütün icazələr
SELECT r.id, p.id FROM roles r, permissions p WHERE r.name = 'ROLE_ADMIN'
    ON CONFLICT (role_id, permission_id) DO NOTHING;

-- Moderator üçün maşın və şəkil idarəetməsi
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.name = 'ROLE_MODERATOR'
  AND p.name IN ('CAR_CREATE', 'CAR_UPDATE', 'CAR_DELETE', 'CAR_VIEW', 'IMAGE_UPLOAD', 'IMAGE_DELETE')
    ON CONFLICT (role_id, permission_id) DO NOTHING;

-- User üçün yalnız öz elanını yaratmaq, yeniləmək və baxmaq
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.name = 'ROLE_USER'
  AND p.name IN ('CAR_CREATE', 'CAR_UPDATE', 'CAR_VIEW', 'IMAGE_UPLOAD')
    ON CONFLICT (role_id, permission_id) DO NOTHING;

